async function main() {
  for (const q of questions) {
    const category = await prisma.interviewCategory.upsert({
      where: { slug: categorySlug },
      update: { name: "QA / Software Testing" },
      create: { name: "QA / Software Testing", slug: categorySlug },
    });

    const subcategory = await prisma.interviewSubcategory.upsert({
      where: { slug: q.subcategorySlug },
      update: { name: subcategoryNames[q.subcategorySlug] },
      create: { name: subcategoryNames[q.subcategorySlug], slug: q.subcategorySlug, categoryId: category.id },
    });

    await prisma.interviewQuestion.upsert({
      where: { slug: q.slug },
      update: {
        question: q.question, categoryId: category.id, subcategoryId: subcategory.id,
        experienceLevel: q.experienceLevel, difficulty: q.difficulty, interviewType: q.interviewType,
        shortDescription: q.shortDescription, explanation: q.explanation, sampleAnswer: q.sampleAnswer,
        detailedAnswer: q.detailedAnswer, keyPoints: q.keyPoints, commonMistakes: q.commonMistakes,
        followUpQuestions: q.followUpQuestions, tags: q.tags, isPublished: true,
      },
      create: {
        question: q.question, slug: q.slug, categoryId: category.id, subcategoryId: subcategory.id,
        experienceLevel: q.experienceLevel, difficulty: q.difficulty, interviewType: q.interviewType,
        shortDescription: q.shortDescription, explanation: q.explanation, sampleAnswer: q.sampleAnswer,
        detailedAnswer: q.detailedAnswer, keyPoints: q.keyPoints, commonMistakes: q.commonMistakes,
        followUpQuestions: q.followUpQuestions, tags: q.tags, isPublished: true,
      },
    });
  }
  console.log(`QA / Software Testing seed completed successfully. Seed data: ${questions.length} questions.`);
}

main()
  .catch((error) => { console.error(error); process.exit(1); })
  .finally(async () => { await prisma.$disconnect(); });